        coinsLabel.setFont(FontManager.getRunescapeBoldFont());
        coinsLabel.setForeground(Color.YELLOW);
        coinsLabel.setHorizontalAlignment(SwingConstants.CENTER);
        coinPanel.add(coinsLabel, BorderLayout.CENTER);

